contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address burner, uint256 burnAmount) public payable {
        require(burner == address(this) || c.owner() == address(this));
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        uint256 tsAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(burner);
        if (success && balBefore >= burnAmount && burner == c.owner()) {
            assert(tsBefore - burnAmount == tsAfter && balBefore - burnAmount == balAfter);
        } else {
            assert(tsBefore == tsAfter && balBefore == balAfter);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address burner, uint256 burnAmount) public payable {
        require(burner != address(0));
        require(c.owner() != burner);
        uint256 supplyBefore = c.totalSupply();
        bool ownerRevert = !_callBurnAs(burner, burnAmount);
        if (!ownerRevert) {
            assert(c.totalSupply() == supplyBefore);
        } else {
            assert(true);
        }
    }
    function _callBurnAs(address burner, uint256 amount) internal returns (bool) {
        (bool success,) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        return success;
    }
}

