            // if it succeeds (try), we must check totalSupply didn't decrease.
            assertTrue(c.totalSupply() == totalSupplyBefore);
        } catch {
            // Reverted, so totalSupply cannot have changed.
            assertTrue(c.totalSupply() == totalSupplyBefore);
