        uint256 balOwnerBefore = c.balanceOf(address(this));
        uint256 balUser1Before = c.balanceOf(user1);
        uint256 balUser2Before = c.balanceOf(user2);

        // The owner calls burn(burnAmount).
        vm.prank(address(this));
        c.burn(burnAmount);

        // Compute actual sum of balances for the three accounts after burn.
        uint256 sumBalances = c.balanceOf(address(this)) + c.balanceOf(user1) + c.balanceOf(user2);

