pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address owner) public {
        // 1. ensure owner is not the zero address
        vm.assume(owner != address(0));
        // mint tokens to owner and transfer ownership (the reference contract allows minting by owner only)
        vm.startPrank(c.owner());
        // set up a reasonable totalSupply so burn can be performed
        uint256 mintAmount = burnAmount + 1;
        c.mintToken(owner, mintAmount);
        // transfer ownership to the fuzzed owner
        // The reference contract has an owned() function that requires msg.sender == owner, but no direct setter.
        // The constructor sets owner = payable(msg.sender). To change owner we deploy with initial owner = this test contract.
        vm.stopPrank();
        // Since we cannot change owner without an onlyOwner function, we fuzz the burn call from the actual owner.
        // The actual owner is the test contract itself, but that address may not hold balance. We instead fuzz the initialSupply.
        // Actually the constructor is called in setUp with (0, 0, 0). The initial owner is address(this).
        // We cannot change owner easily. So we just use the initial owner (address(this)) and fuzz burn from there.
        // But the test function already receives an 'owner' parameter; we can ignore it and use a single known actor.
        // The bug is independent of who calls burn, as long as the caller is the owner. So we just use address(this) as the owner.
        // To satisfy the fuzzer requirement of at least one param, we keep the burnAmount param.
        address realOwner = address(this);
        uint256 initialSupply = 1000000;
        // Re-deploy c with a meaningful supply so burn is possible
        c = new C(initialSupply, "t", "s");
        realOwner = address(this); // after redeploy, owner is still this
        // 2. perform burn
        vm.prank(realOwner);
        c.burn(burnAmount);
        // 3. compute sum of all balances and compare to totalSupply
        // We cannot list all addresses, but we can check that a specific holder's balance plus the owner's balance
        // does not exceed expectations. However a general rule must hold for ALL inputs.
        // The simplest invariant: for the single known address that holds tokens (the owner),
        // balanceOf[owner] + totalSupply == totalSupply - burnAmount? No, that's not general.
        // A general rule must be proven for any state. We do not know other holders.
        // Instead, we can assert that balanceOf[msg.sender] after burn is <= balanceBefore - burnAmount,
        // but that's also not general.
        // Since we cannot iterate over all addresses, we use a different approach:
        // The totalSupply after burn must equal totalSupply_before minus burnAmount.
        // And the owner's balance after burn must equal balance_before minus burnAmount.
        // The difference is that in the buggy version, owner's balance increases.
        // So we assert: balanceOf[realOwner] + burnAmount == initialSupply (if nobody else holds).
        // But we cannot assume nobody else holds.
        // We can assert that balanceOf[realOwner] <= initialSupply - burnAmount.
        // Actually the buggy version increases balance, so it will violate this inequality.
        // That's a property that holds for the reference and fails for the bug.
        uint256 ownerBalance = c.balanceOf(realOwner);
        assertTrue(ownerBalance <= initialSupply * (10 ** uint256(0)) - burnAmount);
    }
}

