import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address target, uint256 mintedAmount, address pranker) public {
        vm.assume(target != address(0));
        vm.assume(mintedAmount > 0);
        vm.assume(pranker != address(0));
        vm.prank(pranker);
        c.mintToken(target, mintedAmount);
        assertTrue(c.totalSupply() == mintedAmount);
    }
}

