pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address target, uint256 mintedAmount) public {
        // Keep the domain wide; only exclude the zero address and require the owner to be the caller
        vm.assume(target != address(0));
        // The onlyOwner modifier requires msg.sender == owner (setUp deployed with the test contract as owner)
        // We prank as the test contract itself, which is the owner
        c.mintToken(target, mintedAmount);

        // The invariant: totalSupply must equal the sum of all balances (only two accounts have balances: owner and target)
        // We compute the sum of the two known balances and compare against totalSupply
        uint256 sumBalances = c.balanceOf(address(this)) + c.balanceOf(target);
        assertTrue(sumBalances == c.totalSupply());
    }
}

