pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 mintedAmount, address target) public {
        vm.assume(target != address(0));
        vm.assume(mintedAmount > 0 && mintedAmount <= type(uint256).max - c.balanceOf(target));
        vm.assume(mintedAmount <= type(uint256).max - c.totalSupply());
        uint256 prevTotal = c.totalSupply();
        c.mintToken(target, mintedAmount);
        uint256 newTotal = c.totalSupply();
        assertTrue(newTotal - prevTotal == mintedAmount);
    }
}

