pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, address target, uint256 mintedAmount) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(mintedAmount < type(uint256).max / 2);
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(target);
        vm.prank(caller);
        c.mintToken(target, mintedAmount);
        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(target);
        bool unchanged = (supplyAfter == supplyBefore) && (balanceAfter == balanceBefore);
        assertTrue(unchanged);
    }
}
